<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Sparkles, Plus, Check, Trash2, ArrowUp, ArrowDown, Download, Save, Maximize2, Minimize2 } from '@lucide/vue'
import { recruiterResults, recruiterQuestions, recruiterSourceLabel, recruiterActionLabel, recruiterExport, saveRecruiterText, type RecruiterConversation, type RecruiterPlanQuestion, type RecruiterAction } from '../recruiter-assistant'
const props = defineProps<{ conversation: RecruiterConversation | null; busy: boolean; name: string; job: string; expanded?: boolean }>()
const emit = defineEmits<{ request: [action: RecruiterAction]; save: [questions: RecruiterPlanQuestion[], notes: string]; expand: [] }>()
const tab = ref<'analysis'|'plan'>('analysis'); const selectedId = ref('')
const questions = ref<RecruiterPlanQuestion[]>([]); const notes = ref('')
const results = computed(() => recruiterResults(props.conversation))
watch(results, (items, before) => { if (!items.some(m => m.id === selectedId.value) || selectedId.value === before?.[0]?.id) selectedId.value = items[0]?.id || '' })
const selected = computed(() => results.value.find(m => m.id === selectedId.value) || results.value[0])
const suggestions = computed(() => recruiterQuestions(props.conversation))
const fingerprint = (q: RecruiterPlanQuestion[], n: string) => JSON.stringify([q.map(i => [i.message_id, i.question]), n])
const saved = ref(''); const dirty = computed(() => fingerprint(questions.value, notes.value) !== saved.value)
const readonly = computed(() => !props.conversation || props.conversation.archived)
watch(() => props.conversation, (current, before) => {
  if (!current) return
  const incoming = fingerprint(current.plan, current.notes)
  // Polling and new AI replies must not replace an unsaved interview outline.
  if (current.session_id !== before?.session_id || !dirty.value || incoming === fingerprint(questions.value, notes.value)) {
    questions.value = current.plan.map(q => ({ ...q })); notes.value = current.notes; saved.value = incoming
  }
}, { immediate: true })
function add(item: RecruiterPlanQuestion) { if (!readonly.value && questions.value.length < 30 && !questions.value.some(q => q.question === item.question)) questions.value.push(item) }
function has(question: string) { return questions.value.some(q => q.question === question) }
function move(index: number, offset: number) { const target = index + offset; if (target >= 0 && target < questions.value.length) [questions.value[index], questions.value[target]] = [questions.value[target]!, questions.value[index]!] }
function exportPlan() { if (props.conversation) saveRecruiterText(recruiterExport(props.conversation, props.name, props.job, 'plan'), props.name + '-面试提纲') }
function resetToSaved() { const current = props.conversation; if (current) { questions.value = current.plan.map(q => ({ ...q })); notes.value = current.notes; saved.value = fingerprint(current.plan, current.notes) } }
function showPlan() { tab.value = 'plan' }
defineExpose({ showPlan, dirty, resetToSaved })
</script>

<template>
  <section :class="['recruiter-results', { 'results-expanded': expanded }]" aria-label="招聘 AI 分析结果与面试提纲">
    <header class="results-heading"><div><Sparkles :size="16" /><h3>一起核对结果</h3></div><button class="text-link result-expand" @click="emit('expand')"><component :is="expanded ? Minimize2 : Maximize2" :size="12" />{{ expanded ? '返回对话' : '展开阅读' }}</button></header>
    <div class="results-tabs" role="group" aria-label="招聘分析结果视图"><button :aria-pressed="tab === 'analysis'" @click="tab = 'analysis'">分析与依据</button><button :aria-pressed="tab === 'plan'" @click="tab = 'plan'">面试提纲 <span v-if="questions.length">{{ questions.length }}</span><i v-if="dirty" aria-label="有未保存修改" /></button></div>
    <div v-if="tab === 'analysis'" class="results-scroll">
      <template v-if="selected"><label class="results-select">查看分析记录<select v-model="selectedId"><option v-for="m in results" :key="m.id" :value="m.id">{{ recruiterActionLabel[m.action] }} · {{ new Date(m.created_at).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }}</option></select></label><article class="result-answer"><span class="result-kind">{{ recruiterActionLabel[selected.action] }}</span><h4>从经历中理解可能的合作</h4><p>{{ selected.text }}</p><small v-if="selected.partial">材料较长，本轮仅分析部分原文。</small></article>
        <section class="result-evidence"><h4>结论的原文依据 <span>{{ selected.citations?.length || 0 }} 处</span></h4><blockquote v-for="(c, i) in selected.citations" :key="i"><small>{{ recruiterSourceLabel[c.source] }}</small>{{ c.quote }}</blockquote><p v-if="!selected.citations?.length" class="results-muted">这条回答没有可展示的材料引用。</p></section>
        <section v-if="selected.questions?.length" class="result-questions"><h4>值得进一步了解</h4><article v-for="q in selected.questions" :key="q"><p>{{ q }}</p><button class="secondary" :disabled="readonly || busy || has(q) || questions.length >= 30" @click="add({ message_id: selected.id, question: q, citations: selected.citations }); tab = 'plan'"><Check v-if="has(q)" :size="12" /><Plus v-else :size="12" />{{ has(q) ? '已加入' : '加入提纲' }}</button></article></section>
      </template>
      <div v-else class="results-empty"><Sparkles :size="27" /><h4>让结论和依据放在一起。</h4><p>完成一次对话后，在这里核对简历精华、业务关联与原文依据。</p><button class="secondary" :disabled="readonly || busy || !conversation?.model.available" @click="emit('request', 'summary')">整理简历精华</button></div>
    </div>
    <div v-else class="results-scroll plan-scroll"><p class="plan-intro">选择值得沟通的问题，按你的面试顺序排列。提纲保存在这次对话中。</p><p v-if="conversation?.archived" class="plan-history-note">这是历史对话的已保存提纲，仅供查看和导出。</p>
      <div class="plan-list"><article v-for="(q, i) in questions" :key="q.question" class="plan-question"><header><span>{{ String(i + 1).padStart(2, '0') }}</span><div v-if="!readonly"><button class="icon-button" :disabled="busy || i === 0" aria-label="上移问题" @click="move(i, -1)"><ArrowUp :size="13" /></button><button class="icon-button" :disabled="busy || i === questions.length - 1" aria-label="下移问题" @click="move(i, 1)"><ArrowDown :size="13" /></button><button class="icon-button danger" :disabled="busy" aria-label="移除问题" @click="questions.splice(i, 1)"><Trash2 :size="13" /></button></div></header><p>{{ q.question }}</p><details v-if="q.citations?.length"><summary>查看追问依据</summary><blockquote v-for="(c, ci) in q.citations" :key="ci"><small>{{ recruiterSourceLabel[c.source] }}</small>{{ c.quote }}</blockquote></details></article></div>
      <p v-if="!questions.length" class="plan-placeholder">还没有选定的问题。从下方建议中添加，或先让 AI 准备面试追问。</p>
      <section v-if="!readonly" class="plan-suggestions"><header><h4>对话中的追问建议</h4><button class="text-link" :disabled="busy || !conversation?.model.available" @click="emit('request', 'interview')">生成追问</button></header><button v-for="q in suggestions" :key="q.question" :disabled="busy || has(q.question) || questions.length >= 30" @click="add(q)"><Check v-if="has(q.question)" :size="13" /><Plus v-else :size="13" /><span>{{ q.question }}</span></button><p v-if="!suggestions.length" class="results-muted">当前对话尚未生成追问建议。</p></section>
      <label class="plan-notes">招聘方沟通备注<textarea v-model="notes" :disabled="readonly || busy" maxlength="4000" rows="3" placeholder="记录计划了解的重点；个人记录不作为候选人的经历事实。" /></label>
    </div>
    <footer v-if="tab === 'plan'" class="plan-footer"><small>{{ readonly ? '历史提纲' : dirty ? '有未保存的修改' : '已与当前保存内容同步' }}</small><div><button class="secondary" :disabled="dirty || !conversation || !conversation.plan.length && !conversation.notes" @click="exportPlan"><Download :size="13" />导出</button><button v-if="!readonly" class="primary" :disabled="busy || !dirty" @click="emit('save', questions, notes)"><Save :size="13" />保存提纲</button></div></footer>
    <footer v-else class="results-footer">材料未说明的部分，仅作提示。建议由你核对。</footer>
  </section>
</template>

<style scoped>
