h4{font-size:13px;line-height:1.8}.result-evidence h4 span{font-weight:400;font-size:10px;color:var(--text-muted);margin-left:6px}.recruiter-results blockquote{margin:11px 0 0;padding:12px;border:1px solid var(--border-soft);border-left:3px solid var(--brand);background:white;border-radius:0 7px 7px 0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.9}.recruiter-results blockquote small{display:block;font-size:10px;color:var(--text-muted);margin-bottom:5px}.result-questions article{padding:13px 0;border-bottom:1px solid var(--border-soft)}.result-questions article p{font-size:12px;line-height:1.9}.result-questions article .secondary{font-size:10px;min-height:28px;padding:5px 8px;margin-top:9px}.results-footer{font-size:10px;line-height:1.8;color:var(--text-muted);padding:12px 18px;border-top:1px solid var(--border-soft);flex-shrink:0}.results-empty{padding:40px 6px;color:var(--brand-ink);display:flex;flex-direction:column;align-items:flex-start;gap:17px}.results-empty h4{font-size:17px;color:var(--text-main)}.results-empty p{font-size:13px;line-height:1.95;color:var(--text-muted)}.results-empty .secondary{font-size:12px;min-height:34px;padding:7px 10px}.plan-intro,.plan-history-note{font-size:12px;color:var(--text-muted);line-height:1.9;margin-bottom:15px}.plan-history-note{color:var(--brand-ink)}.plan-list{display:grid;gap:11px}.plan-question{border:1px solid var(--border-soft);border-radius:9px;background:#fff;padding:13px}.plan-question>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:9px}.plan-question>header>span{font-size:11px;color:var(--brand-ink);font-weight:650}.plan-question>header>div{display:flex;gap:4px}.plan-question .icon-button{padding:4px;min-width:25px;min-height:25px}.plan-question>p{font-size:13px;line-height:1.9;overflow-wrap:anywhere}.plan-question summary{font-size:10px;cursor:pointer;margin-top:11px;color:var(--brand-ink)}.plan-placeholder{padding:20px 14px;border:1px dashed var(--bra